"""Six trial contracts. Worker identities come from the archived scripts.

Route descriptions are design notes, not replacement game narration. The
compiled action graph retains the script's actual guards and native calls.
Spatial names/push directions must not be inferred from these worker numbers.
"""


def trial(name, script, sockets, mechanics, normal, treasure, reset, fields,
          exit_worker, exit_room, treasure_worker, treasure_id, treasure_bit):
    return dict(name=name, script=script, socket_workers=sockets,
                mechanics=mechanics, normal_route=normal, treasure_route=treasure,
                reset_policy=reset, fields=fields,
                completion=dict(worker=exit_worker, room=exit_room),
                treasure=dict(worker=treasure_worker, id=treasure_id,
                              flag_offset=0xA70, mask=treasure_bit))


